def mk(slug, **k):
    c = dict(k); n = c['niche']
    c.setdefault('before_label', 'instagram.com/' + c['handle'])
    c.setdefault('ann_m', 'Envíos a toda España')
    c.setdefault('rev_h', 'Así lo contáis en Instagram')
    c.setdefault('igrid', ['x2', 'l3', 'p5', 'l1', 'x3', 'l2'])
    c.setdefault('hero_pos', 'center'); c.setdefault('hero_pos_m', '78% center'); c.setdefault('close_pos', 'center 35%')
    c.setdefault('ba_h2', 'Vuestro Instagram hoy,<br>y la tienda que os montaríamos.')
    c.setdefault('ba_p', f'Deslizad la barra. A la izquierda, @{c["handle"]} tal y como está hoy: se ve todo, pero no se puede comprar con un toque. A la derecha, la misma marca y lo mismo que vendéis, convertido en una tienda online.')
    a = dict(ADS[n]); a.update(c.get('ads', {})); c['ads'] = a
    if 'pdp' in c:
        c['pdp'] = dict(dict(t1='Foto de estudio' if n == 'moda' else 'Foto de producto', t2='Puesto' if n == 'moda' else 'En casa', t3='De cerca'), **c['pdp'])
    # leaks: the web first, then the niche
    ws = c['web_state']; city = c['city_short']
    if ws == 'none':
        l1 = ('Sin web, sin escaparate', f'Quien busca «{SEARCH[n].format(city=city)}» en Google no encuentra dónde compraros.')
    elif ws == 'down':
        l1 = ('Web caída', f'{c["domain"]} no carga: quien os busca en Google llega a una página de error.')
    else:
        l1 = ('Tienda online a medias', c['web_note'])
    lk = [l1, LEAK_MSG[n], ('Con la persiana bajada, cero ventas', 'Fuera de horario, en festivos o en vacaciones, la tienda no vende.'),
          ('Sin respuesta, sin venta', c.get('leak4', 'Un mensaje que se contesta tarde es un cliente que compra en otro sitio.')), LEAK_5[n],
          ('Crecer = otro local', 'Hoy, vender más significa más alquiler, más personal y más riesgo.')]
    c['diag']['leaks'] = c['diag'].get('leaks') or lk
    SHOPS[slug] = c


